def encode_inputs(left_digits: torch.Tensor, right_digits: torch.Tensor) -> torch.Tensor:
    """Editable reversible operand formatting; each input is [batch, 4], LSB first.

    Pair tokens are the seed representation only. Never compute answers here.
    """
    sentinel = torch.full_like(left_digits[:, :1], 10)
    return torch.cat((left_digits, sentinel, right_digits, sentinel), dim=1)

